function PVPArenaGroupMatchChart:__init()
    self.groupIndex        = 1

    ---@type PVPArenaDojo
    self.pvpArenaDojo      = pvpArenaComponent:GetPVPArenaDojo()
    ---@type PVPArenaEntryDojo
    self.pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    --- 是否是观众
    self.isAudience        = checkNumber(self.pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience

end

function PVPArenaGroupMatchChart:__delete()
    self.groupIndex        = nil
    self.pvpArenaDojo      = nil
    self.pvpArenaEntryDojo = nil
end

function PVPArenaGroupMatchChart:Awake()
    UIEventProxy.Create(self.BtnTurnPageL.gameObject).onPointerClick  = Bind(self, self.OnClickLeftButtonAction)
    UIEventProxy.Create(self.BtnTurnPageR.gameObject).onPointerClick = Bind(self, self.OnClickRightButtonAction)
end

function PVPArenaGroupMatchChart:OnDestroy()
    self:RemoveAgainstStateCo()
    self:UnRegisterCountDown()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end

