function PVPArenaGroupMatchChart:RefreshUI(oldGroupIndex)
    local seasonFlag       = pvpArenaComponent:GetSeasonFlag()
    local pvpArenaEntryDojo= self.pvpArenaEntryDojo
    local battleStatus     = checkNumber(pvpArenaEntryDojo.battleStatus)
    local mainPanelStatus  = pvpArenaComponent:GetMainPanelStatus()

    --- 只要不是观众 并且 不是战斗准备阶段 并且 不是观赛 则可以编队
    self.isCanEditTeam     = not self.isAudience and battleStatus ~= Constants.PVPArenaBattleStatus.Prepare and mainPanelStatus ~= Constants.PVPArenaMainPanelStatus.WatchTheMatch
    local leftQuizTicketBuyTimes = checkNumber(self.pvpArenaDojo.leftQuizTicketBuyTimes)
    self.isCanQuiz         = seasonFlag == Constants.PVPArenaSeasonFullStatus.Quiz and leftQuizTicketBuyTimes > 0 and self.isAudience
    self.seasonFlag        = seasonFlag
    self.battleRound       = checkNumber(self.pvpArenaDojo.battleRound)
    if battleStatus >= Constants.PVPArenaBattleStatus.Prepare then
        self.battleRound = self.battleRound - 1
    end

    self.playerId = pvpArenaComponent:GetPlayerId()

    self:RefreshTxtGroup()
    self:RefreshPageBtnShowState()
    self:RefreshGroupSelectState(oldGroupIndex)
    self:RefreshAllPlayerHeadNode()
    if not self.isAudience then
        self:RefreshCountDown()
    end
end

---RefreshTxtGroup
---刷新小组文字
function PVPArenaGroupMatchChart:RefreshTxtGroup()
    local char = string.upper(string.char(self.groupIndex - 1 + aByte))
    self.TxtGroup.text = char
end

---RefreshPageBtnShowState
---刷新小组切换页面显示状态
function PVPArenaGroupMatchChart:RefreshPageBtnShowState()
    KTool.SetActive(self.BtnTurnPageL.gameObject, self.groupIndex > 1)
    KTool.SetActive(self.BtnTurnPageR.gameObject, self.groupIndex < GroupCount)
end

---RefreshTeamSelect
---刷新小组选择状态
---@param oldGroupIndex number 旧的小组下标
function PVPArenaGroupMatchChart:RefreshGroupSelectState(oldGroupIndex)
    local transform = self.TeamSelect.transform
    if oldGroupIndex then
        local cell = transform:GetChild(oldGroupIndex - 1)
        local name = "pvp_map_ico_team_02"
        CfUtils.FillImage(cell.gameObject, string.format("%s%s.png", BasePath, name))
    end
    local name = "pvp_map_ico_team_01"
    local cell = transform:GetChild(self.groupIndex - 1)
    CfUtils.FillImage(cell.gameObject, string.format("%s%s.png", BasePath, name))
end

---RefreshCountDown
---刷新倒计时
function PVPArenaGroupMatchChart:RefreshCountDown()
    local seasonFlag = self.seasonFlag
    --- 小组赛才显示时间
    local isShowCountDown = seasonFlag == Constants.PVPArenaSeasonFullStatus.Group
    KTool.SetActive(self.TxtCountdown.gameObject, isShowCountDown)

    if not isShowCountDown then
        self:UnRegisterCountDown()
    else
        self:RegisterCountDown()
    end

    local countDownTipText
    if seasonFlag == Constants.PVPArenaSeasonFullStatus.Group then
        countDownTipText = localize("预计下轮开始时间")
    else
        countDownTipText = localize("距离比赛开始")
    end
    self.TxtCountdown.text = countDownTipText

end

function PVPArenaGroupMatchChart:RegisterCountDown()
    if self.__OnCountDownUpdate then return end
    self.__OnCountDownUpdate = Events.AddListener(Constants.EventNames.PVPArenaCountDownUpdate, Bind(self, self.OnCountDownUpdate))
end
function PVPArenaGroupMatchChart:UnRegisterCountDown()
    if self.__OnCountDownUpdate then
        Events.RemoveListener(Constants.EventNames.PVPArenaCountDownUpdate, self.__OnCountDownUpdate)
        self.__OnCountDownUpdate = nil
    end
end

---RefreshAllPlayerHeadNode
---刷新所有玩家信息节点
function PVPArenaGroupMatchChart:RefreshAllPlayerHeadNode()
    local pvpArenaDojo      = self.pvpArenaDojo
    local pvpArenaEntryDojo = self.pvpArenaEntryDojo
    local map               = checkTable(pvpArenaDojo.map)
    local matcherInfo       = checkTable(pvpArenaDojo.matcherInfo)
    local groupWheelScope   = pvpArenaComponent:GetGroupWheelScope()
    local groupWheelCount   = pvpArenaComponent:GetGroupWheelCount()
    local oneGroupScope     = groupWheelScope[self.groupIndex]
    local displayWheelCount = groupWheelCount + 1

    local headLayers   = {self.HeadLayer1, self.HeadLayer2, self.HeadLayer3, self.HeadLayer4, self.HeadLayer5}
    local lineLayers   = {self.LineLayer1, self.LineLayer2, self.LineLayer3, self.LineLayer4}

    local isInBattle    = checkNumber(pvpArenaEntryDojo.battleStatus) == Constants.PVPArenaBattleStatus.InBattle
    local winPlayerId2win = PVPArenaUtils.CreateWinPlayerId2win(map, pvpArenaComponent:GetCurWheel(), oneGroupScope)

    for wheel = 1, displayWheelCount do
        ---@type UnityEngine.RectTransform
        local headLayer    = headLayers[wheel]
        --- 最后一轮是nil
        ---@type UnityEngine.RectTransform
        local lineLayer    = lineLayers[wheel]
        local oneWheelGroupScope = oneGroupScope[wheel]
        local leftNum, rightNum = SafeUnpack(oneWheelGroupScope)
        local isFirstWheel = wheel == 1
        local isDisplayWheel = wheel == displayWheelCount

        for position = checkInt(leftNum), checkInt(rightNum), 2 do
            --- 还是创建一场的对阵数据  创建单个玩家的数据 会有重复数据
            local oneMatchChartData = PVPArenaUtils.CreateOneMatchChartData(position, wheel, isInBattle, map, matcherInfo)
            --- 每轮的下标从0开始
            local index = position - leftNum
            if isFirstWheel then
                local idx = math.floor(index / 2)
                local headNode = headLayer:GetChild(idx)
                self:RefreshAgainstHeadDoubleNode(headNode.gameObject, oneMatchChartData)

                local lineNode = lineLayer:GetChild(idx)
                self:RefreshAgainstStateNode(lineNode.gameObject, oneMatchChartData, winPlayerId2win, wheel)

            --- 展示轮只需展示冠军头像
            elseif isDisplayWheel then
                local headNode = headLayer:GetChild(index)
                self:RefreshAgainstHeadSingleNode(headNode.gameObject, oneMatchChartData, index, true)

            else
                local headNode1 = headLayer:GetChild(index)
                self:RefreshAgainstHeadSingleNode(headNode1.gameObject, oneMatchChartData, index)

                local nextIndex = index + 1
                local headNode2 = headLayer:GetChild(nextIndex)
                self:RefreshAgainstHeadSingleNode(headNode2.gameObject, oneMatchChartData, nextIndex)

                local idx = math.floor(index / 2)
                local lineNode = lineLayer:GetChild(idx)
                self:RefreshAgainstStateNode(lineNode.gameObject, oneMatchChartData, winPlayerId2win, wheel)
            end
        end

    end

    self:CreateAgainstStateCo()

end

---RefreshAgainstHeadDoubleNode
---刷新对抗节点双头像版界面
---@param gameObject UnityEngine.GameObject
---@param oneMatchChartData table
function PVPArenaGroupMatchChart:RefreshAgainstHeadDoubleNode(gameObject, oneMatchChartData)
    ---@type PVPArenaAgainstHeadDoubleNode
    local env = GetLuaScr(gameObject, PVPArenaAgainstHeadDoubleNodePath)
    if not isNull(env) then
        env:SetBattleRound(self.battleRound)
        env:SetIsAudience(self.isAudience)
        env:RefreshUI(oneMatchChartData, self.playerId, self.isCanQuiz)
    end
end

---RefreshAgainstHeadSingleNode
---@param gameObject UnityEngine.GameObject
---@param oneMatchChartData table
---@param index number 下标
---@param isLastWheel boolean 是否是最后一轮
function PVPArenaGroupMatchChart:RefreshAgainstHeadSingleNode(gameObject, oneMatchChartData, index, isLastWheel)
    ---@type PVPArenaAgainstHeadSingleNode
    local env = GetLuaScr(gameObject, PVPArenaAgainstHeadSingleNodePath)
    if not isNull(env) then
        env:SetIsAudience(self.isAudience)
        env:RefreshUI(oneMatchChartData, isLastWheel, index, self.playerId)
    end
end

---RefreshAgainstStateNode
---@param gameObject UnityEngine.GameObject
---@param oneMatchChartData table   一场对阵数据 leftPlayerId leftInfo rightPlayerId rightInfo positionWheel matchResultIndex inBattle
function PVPArenaGroupMatchChart:RefreshAgainstStateNode(gameObject, oneMatchChartData, winPlayerId2win, wheel)
    ---@type PVPArenaMatchChartAgainstStateNode
    local env  = CfUtils.GetLuaScr(gameObject, PVPArenaMatchChartAgainstStateNodePath)
    if not isNull(env) then
        env:SetWheel(wheel)
        env:SetPlayerId2Group(pvpArenaComponent:GetPlayerId2Group())
        env:RefreshUI(oneMatchChartData, winPlayerId2win, false)
    end
end

function PVPArenaGroupMatchChart:SwitchPage(deltaNum)
    local oldGroupIndex = self.groupIndex
    self.groupIndex = oldGroupIndex + deltaNum
    self:RefreshUI(oldGroupIndex)
end

---JumpPlayerGroup
---跳转到当前玩家所在的组别
function PVPArenaGroupMatchChart:JumpPlayerGroup()
    local playerId2Group = pvpArenaComponent:GetPlayerId2Group()
    local playerId       = pvpArenaComponent:GetPlayerId()
    local groupInfo      = playerId2Group[tostring(playerId)]
    local oldGroupIndex  = self:GetGroupIndex()
    self:SetGroupIndex(groupInfo.groupIndex)
    self:RefreshUI(oldGroupIndex)
end

function PVPArenaGroupMatchChart:CreateAgainstStateCo()
    if self.againstStateCo then return end
    local groupWheelCount   = pvpArenaComponent:GetGroupWheelCount()
    self.againstStateCo = cs_coroutine.start(function()
        local PVPArenaMatchChartPlayEffect = Constants.EventNames.PVPArenaMatchChartPlayEffect
        local wheel = 1
        while true do
            Events.Broadcast(PVPArenaMatchChartPlayEffect, wheel)
            cs_coroutine.yield_return(WaitForSeconds)
            wheel = wheel == groupWheelCount and 1 or wheel + 1
        end
    end)
end

function PVPArenaGroupMatchChart:RemoveAgainstStateCo()
    if not isNull(self.againstStateCo) then
        cs_coroutine.stop(self.againstStateCo)
        self.againstStateCo = nil
    end
end

function PVPArenaGroupMatchChart:OnCountDownUpdate()
    local pvpArenaEntryDojo = self.pvpArenaEntryDojo
    local seasonFlag        = self.seasonFlag
    if seasonFlag == Constants.PVPArenaSeasonFullStatus.Group then
        self.TxtTime.text = GetTimeHMS2(pvpArenaComponent:CalcBattleNextWheelSeconds())
    else
        self.TxtTime.text = GetTimeHMS2(pvpArenaEntryDojo.nextStageLeftSeconds)
    end
end

